function hash(buffer) {
  return createHash("sha256").update(buffer).digest("hex");
}

async function currentHash(entry) {
  try {
    return hash(await readFile(resolve(root, entry.path)));
  } catch (error) {
    if (error?.code === "ENOENT") return null;
    throw error;
  }
}

const current = new Map();
for (const entry of manifest) current.set(entry.path, await currentHash(entry));

const alreadyApplied = manifest.every((entry) => current.get(entry.path) === entry.after);
if (alreadyApplied) {
  console.log("✓ 4.6.5 Legacy Storage Retirement ist bereits vollständig angewendet. 0 Änderungen.");
  process.exit(0);
}

const mismatches = manifest.filter((entry) => current.get(entry.path) !== entry.before);
if (mismatches.length) {
  console.error("Abbruch: Der Repository-Stand entspricht nicht dem geprüften 4.6.4-Ausgangsstand.");
  for (const entry of mismatches.slice(0, 12)) {
    console.error(`- ${entry.path}: erwartet ${entry.before ?? "nicht vorhanden"}, gefunden ${current.get(entry.path) ?? "nicht vorhanden"}`);
  }
  console.error("Es wurde keine Datei verändert.");
  process.exit(1);
}

for (const entry of manifest) {
  const file = resolve(root, entry.path);
  if (entry.content === null) {
    await rm(file, { force: true });
    console.log(`✓ entfernt: ${entry.path}`);
    continue;
  }
  await mkdir(dirname(file), { recursive: true });
  await writeFile(file, Buffer.from(entry.content, "base64"));
  console.log(`✓ aktualisiert: ${entry.path}`);
}

for (const entry of manifest) {
  const actual = await currentHash(entry);
  if (actual !== entry.after) {
    throw new Error(`Nachprüfung fehlgeschlagen: ${entry.path}`);
  }
}

console.log(`✓ 4.6.5 Legacy Storage Retirement vollständig angewendet (${manifest.length} Zieldateien).`);
